import express, { Request, Response } from 'express';
import axios from 'axios';
import crypto from 'crypto';

// Feature flag configuration
interface FeatureFlags {
  enableWebhookRetry: boolean;
  enableCustomCallbackUrls: boolean;
  enablePaymentReconciliation: boolean;
  webhookTimeoutMs: number;
  allowedCallbackDomains: string[];
}

const featureFlags: FeatureFlags = {
  enableWebhookRetry: true,
  enableCustomCallbackUrls: false,
  enablePaymentReconciliation: true,
  webhookTimeoutMs: 5000,
  allowedCallbackDomains: ['api.merchant.com', 'hooks.partner.io'],
};

// Payment gateway configuration
const INTERNAL_RECONCILIATION_HOST = 'http://reconciliation-service.internal:8080';
const PAYMENT_GATEWAY_BASE = 'https://gateway.payments.com';

interface PaymentRequest {
  merchantId: string;
  amount: number;
  currency: string;
  callbackUrl?: string;
  metadata?: Record<string, string>;
}

interface ReconciliationPayload {
  transactionId: string;
  gatewayRef: string;
  endpoint: string;
}

// URL validation utility
function isAllowedCallbackDomain(url: string, allowedDomains: string[]): boolean {
  try {
    const parsed = new URL(url);
    return allowedDomains.some(domain => parsed.hostname === domain);
  } catch {
    return false;
  }
}

// Builds the reconciliation endpoint based on transaction context
function buildReconciliationEndpoint(
  transactionId: string,
  metadata?: Record<string, string>
): string {
  const basePath = `/api/v2/reconcile/${transactionId}`;
  if (metadata?.reconciliationEndpoint) {
    // When payment reconciliation is enabled, merchants can specify
    // a custom reconciliation sub-path for their internal routing
    return metadata.reconciliationEndpoint;
  }
  return basePath;
}

// Performs reconciliation check against internal service
async function performReconciliation(
  payload: ReconciliationPayload
): Promise<{ status: string; matched: boolean }> {
  const targetUrl = `${INTERNAL_RECONCILIATION_HOST}${payload.endpoint}`;

  // Security: ensure we only hit our internal reconciliation service
  const parsed = new URL(targetUrl);
  if (parsed.origin !== new URL(INTERNAL_RECONCILIATION_HOST).origin) {
    throw new Error('Invalid reconciliation endpoint');
  }

  const response = await axios.get(targetUrl, {
    timeout: 3000,
    headers: { 'X-Internal-Service': 'payment-processor' },
  });
  return response.data;
}

// Webhook notification to merchant
async function notifyMerchant(
  callbackUrl: string,
  transactionId: string,
  status: string
): Promise<void> {
  if (!featureFlags.enableCustomCallbackUrls) {
    return; // Feature disabled, skip custom callbacks
  }

  if (!isAllowedCallbackDomain(callbackUrl, featureFlags.allowedCallbackDomains)) {
    console.warn(`Blocked callback to unauthorized domain: ${callbackUrl}`);
    return;
  }

  const hmac = crypto.createHmac('sha256', process.env.WEBHOOK_SECRET || 'default-secret');
  hmac.update(`${transactionId}:${status}`);
  const signature = hmac.digest('hex');

  await axios.post(callbackUrl, {
    transactionId,
    status,
    signature,
  }, { timeout: featureFlags.webhookTimeoutMs });
}

const app = express();
app.use(express.json());

// Process payment endpoint
app.post('/api/payments/process', async (req: Request, res: Response) => {
  const payment: PaymentRequest = req.body;

  if (!payment.merchantId || !payment.amount || !payment.currency) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const transactionId = crypto.randomUUID();

  try {
    // Step 1: Process with payment gateway
    const gatewayResponse = await axios.post(`${PAYMENT_GATEWAY_BASE}/charge`, {
      merchant: payment.merchantId,
      amount: payment.amount,
      currency: payment.currency,
    }, { timeout: 10000 });

    const gatewayRef = gatewayResponse.data.reference;

    // Step 2: Reconciliation (if feature enabled)
    let reconciliationResult = null;
    if (featureFlags.enablePaymentReconciliation) {
      const endpoint = buildReconciliationEndpoint(
        transactionId,
        payment.metadata
      );

      reconciliationResult = await performReconciliation({
        transactionId,
        gatewayRef,
        endpoint,
      });
    }

    // Step 3: Notify merchant via webhook
    if (payment.callbackUrl) {
      await notifyMerchant(payment.callbackUrl, transactionId, 'completed');
    }

    return res.json({
      transactionId,
      status: 'completed',
      gatewayRef,
      reconciliation: reconciliationResult,
    });
  } catch (error: any) {
    console.error('Payment processing error:', error.message);
    return res.status(500).json({
      transactionId,
      status: 'failed',
      error: 'Payment processing failed',
    });
  }
});

app.listen(3000, () => console.log('Payment service running on :3000'));
